BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;

WITH paid_orders AS (
  SELECT * FROM orders WHERE status = 'paid'
)
SELECT user_id, count(*) FROM paid_orders GROUP BY user_id;

CREATE UNIQUE INDEX idx_users_email_active
ON users (email)
WHERE deleted_at IS NULL;

BEGIN;
SELECT * FROM inventory WHERE sku = 'A' FOR UPDATE;
UPDATE inventory SET stock = stock - 1 WHERE sku = 'A';
COMMIT;

SELECT * FROM (
  SELECT orders.*, row_number() OVER (PARTITION BY user_id ORDER BY created_at DESC) AS rn
  FROM orders
) t
WHERE rn = 1;

CREATE UNIQUE INDEX idx_users_email_not_deleted
ON users (email)
WHERE deleted_at IS NULL;

CREATE INDEX idx_users_email_lower ON users (lower(email));

-- planner matches this query to the index above
SELECT * FROM users WHERE lower(email) = lower($1);

create index on events using gin (payload);

-- uses the GIN index (containment)
select * from events where payload @> '{"type": "order_paid"}';

-- does NOT use it: the ->> operator extracts text, GIN cannot help
select * from events where payload ->> 'type' = 'order_paid';

create table request_logs (
  id        bigserial,
  created_at timestamptz not null,
  payload   jsonb
) partition by range (created_at);

create table request_logs_2026_08
  partition of request_logs
  for values from ('2026-08-01') to ('2026-09-01');

-- on the publisher (requires wal_level = logical)
create publication orders_pub for table orders, order_items;

-- on the subscriber
create subscription orders_sub
  connection 'host=... dbname=...'
  publication orders_pub;

-- default for the app user
alter role app_user set statement_timeout = '15s';
alter role app_user set idle_in_transaction_session_timeout = '30s';

-- report user needs longer
alter role report_user set statement_timeout = '5min';

BEGIN;
SELECT balance FROM wallets WHERE user_id = 42 FOR UPDATE;  -- giữ hàng
UPDATE wallets SET balance = balance - 100 WHERE user_id = 42;
COMMIT;                                                      -- khoá nhả ở đây

BEGIN;
UPDATE jobs SET status = 'running'
WHERE id = (
  SELECT id FROM jobs
  WHERE status = 'pending'
  ORDER BY created_at
  FOR UPDATE SKIP LOCKED
  LIMIT 1
)
RETURNING *;
COMMIT;

-- đặt cho riêng phiên chạy migration
SET lock_timeout = '3s';
SET statement_timeout = '60s';
ALTER TABLE orders ADD COLUMN note text;
